  "signal_basis": {
    "component_id": "C057.signal_basis",
    "value": "Evaluation checks fail or evidence is too sparse for causal interpretation. Recording changes can produce apparent improvement, while small cohorts, incomplete follow-up, comparison-group differences and concurrent changes can leave the release effect uncertain.",
    "scope": "Conditional limitations of the release evaluation; these are possible evidential deficiencies, not reported findings.",
