        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans describe measurement and comparison limitations, the conditional evidential failure, and the prospective status of the observations."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C057.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
